<?php declare(strict_types=1);require_once __DIR__.'/bootstrap.php';admin_require_login();$errors=[];if($_SERVER['REQUEST_METHOD']==='POST'){admin_csrf_check();$paymentId=(int)($_POST['payment_id']??0);$decision=(string)($_POST['decision']??'');$reference=trim((string)($_POST['reference']??''));try{$pdo->beginTransaction();$s=$pdo->prepare('SELECT p.*,o.id AS oid,o.total_amount FROM payments p JOIN orders o ON o.id=p.order_id WHERE p.id=? FOR UPDATE');$s->execute([$paymentId]);$p=$s->fetch();if(!$p)throw new RuntimeException('Payment not found.');if($decision==='approve'){if($reference==='')$reference=(string)($p['transaction_reference']??'');if($reference==='')throw new RuntimeException('Enter or confirm the M-Pesa transaction reference before approval.');$dupe=$pdo->prepare('SELECT COUNT(*) FROM payments WHERE transaction_reference=? AND id<>?');$dupe->execute([$reference,$paymentId]);if((int)$dupe->fetchColumn()>0)throw new RuntimeException('That transaction reference is already attached to another payment.');$items=$pdo->prepare('SELECT product_id,product_name,quantity FROM order_items WHERE order_id=?');$items->execute([$p['oid']]);$orderItems=$items->fetchAll();$stockRead=$pdo->prepare('SELECT stock_quantity,is_active FROM products WHERE id=? FOR UPDATE');$stockUpdate=$pdo->prepare('UPDATE products SET stock_quantity=stock_quantity-? WHERE id=? AND stock_quantity>=?');foreach($orderItems as $oi){if($oi['product_id']===null)continue;$stockRead->execute([(int)$oi['product_id']]);$stockRow=$stockRead->fetch();if(!$stockRow||(int)$stockRow['is_active']!==1||(int)$stockRow['stock_quantity']<(int)$oi['quantity'])throw new RuntimeException('Insufficient stock for '.$oi['product_name'].'. Do not approve payment until the order is resolved.');$stockUpdate->execute([(int)$oi['quantity'],(int)$oi['product_id'],(int)$oi['quantity']]);if($stockUpdate->rowCount()!==1)throw new RuntimeException('Stock changed while approving this payment.');}$pdo->prepare("UPDATE payments SET status='successful',transaction_reference=?,provider_receipt=?,paid_at=NOW() WHERE id=?")->execute([$reference,$reference,$paymentId]);$pdo->prepare("UPDATE orders SET payment_status='paid',status=CASE WHEN status='pending' THEN 'confirmed' ELSE status END WHERE id=?")->execute([$p['oid']]);$_SESSION['flash']='Payment approved, stock updated, and order confirmed.';}elseif($decision==='reject'){$pdo->prepare("UPDATE payments SET status='failed',transaction_reference=? WHERE id=?")->execute([$reference?:null,$paymentId]);$pdo->prepare("UPDATE orders SET payment_status='failed' WHERE id=?")->execute([$p['oid']]);$_SESSION['flash']='Payment marked failed; order was not confirmed.';}else throw new RuntimeException('Unknown action.');$pdo->commit();redirect('payments.php');}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$errors[]=$e instanceof RuntimeException?$e->getMessage():'Could not update payment.';}}$rows=$pdo->query("SELECT p.id,p.amount,p.status AS payment_record_status,p.transaction_reference,p.created_at,o.order_number,o.customer_name,o.customer_phone,o.total_amount,o.status AS order_status,o.payment_status FROM payments p JOIN orders o ON o.id=p.order_id ORDER BY p.created_at DESC LIMIT 300")->fetchAll();admin_page_start('Payment approval');foreach($errors as $err):?><div class="alert alert-danger"><?=e($err)?></div><?php endforeach;?><div class="alert alert-warning">Verify the M-Pesa message or official transaction record before approving. A customer-entered reference alone is not proof of payment.</div><div class="panel"><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Order / customer</th><th>Amount</th><th>Reference</th><th>Payment</th><th>Approval</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><strong><?=e($r['order_number'])?></strong><div><?=e($r['customer_name'])?> · <?=e($r['customer_phone'])?></div><small class="text-secondary">Order: <?=e($r['order_status'])?></small></td><td><?=money($r['amount'])?></td><td><?=e($r['transaction_reference']??'—')?></td><td><?=e($r['payment_record_status'])?></td><td><?php if(in_array($r['payment_record_status'],['pending','initiated'],true)):?><form method="post" class="d-grid gap-2"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="payment_id" value="<?=(int)$r['id']?>"><input class="form-control form-control-sm" name="reference" value="<?=e($r['transaction_reference']??'')?>" placeholder="Verified M-Pesa code"><button class="btn btn-sm btn-success" name="decision" value="approve">Approve payment</button><button class="btn btn-sm btn-outline-danger" name="decision" value="reject">Mark failed</button></form><?php else:?><span class="badge <?= $r['payment_record_status']==='successful'?'text-bg-success':'text-bg-secondary'?>"><?=e($r['payment_record_status'])?></span><?php endif;?></td></tr><?php endforeach;?></tbody></table></div></div><?php admin_page_end();?>